import {
	Component,
	Element,
	Event,
	type EventEmitter,
	Host,
	Listen,
	Method,
	Prop,
	State,
	Watch,
	h,
} from "@stencil/core";
import { remove } from "../../../icons";
import { focusVisible } from "../../utils/focus-visible";
import getBootstrapConfig from "../../utils/getBootstrapConfig";
import { color } from "../../utils/token";

/**
 * @since 0.0.11
 * @status experimental
 *
 * @slot nav - Used for grouping tabs in the tab group.
 * @slot - Used for grouping tab panels in the tab group.
 *
 * @part base - The component's base wrapper.
 * @part nav - The tab group navigation container.
 * @part tabs - The container that wraps the slotted tabs.
 * @part active-tab-indicator - An element that displays the currently selected tab. This is a child of the tabs container.
 * @part body - The tab group body where tab panels are slotted in.
 */

@Component({
	tag: "hbr-tab-nav",
	styleUrl: "tab-nav.scss",
	shadow: true,
})
export class TabNav {
	activeTab: HTMLHbrTabElement;
	activeTabIndicator: HTMLElement;
	body: HTMLElement;
	mutationObserver: MutationObserver;
	navEl: HTMLElement;
	resizeObserver: ResizeObserver;
	tabnav: HTMLElement;
	tabs: HTMLElement;

	@State() isVisible = false;

	@Element() host: HTMLHbrTabNavElement;

	@Prop({ reflect: true }) nav = true;

	/** Emitted when a tab is shown. */
	@Event({ eventName: "hbr-tab-show" }) hbrTabShow: EventEmitter<{
		name: string;
	}>;

	/** Emitted when a tab is hidden. */
	@Event({ eventName: "hbr-tab-hide" }) hbrTabHide: EventEmitter<{
		name: string;
	}>;

	@Prop({ mutable: true, reflect: true }) sentiment = "interact";

	/** Enable tab border */
	@Prop({ reflect: true }) border = false;

	/** Set to true to control the tab-nav's state from the application / framework's side */
	@Prop() uncontrolled = false;

	/** make this component no responsive */
	@Prop({ reflect: true }) noResponsive = false;

	/** used in nav */
	@Prop() collapsed = false;

	@Listen("hbr-select")
	menuItemListener(e) {
		const popover = e.target.closest("hbr-tab-popover");
		const tab = popover?.shadowRoot.querySelector("hbr-tab");
		if (tab) {
			this.setActiveTab(tab);
		}
	}

	connectedCallback() {
		this.handleClick = this.handleClick.bind(this);
		this.handleKeyDown = this.handleKeyDown.bind(this);
		this.getAllTabs = this.getAllTabs.bind(this);
		this.setActiveTab = this.setActiveTab.bind(this);
		this.getAllTabFold = this.getAllTabFold.bind(this);
		this.handleClickIcon = this.handleClickIcon.bind(this);
	}

	componentDidLoad() {
		// Set initial tab state when the tabs first become visible
		const observer = new IntersectionObserver((entries, observer) => {
			if (entries[0].intersectionRatio > 0) {
				this.setAriaLabels();
				if (!this.nav) {
					this.setActiveTab(this.getActiveTab() || this.getAllTabs()[0], false);
				}
				observer.unobserve(entries[0].target);
			}
		});
		observer.observe(this.host);

		focusVisible.observe(this.tabnav);

		// Update aria labels if the DOM changes
		this.mutationObserver = new MutationObserver((mutations) => {
			if (
				mutations.some((mutation) => {
					return !["aria-labelledby", "aria-controls"].includes(
						mutation.attributeName,
					);
				})
			) {
				setTimeout(() => this.setAriaLabels());
			}
		});
		this.mutationObserver.observe(this.host, {
			attributes: true,
			childList: true,
			subtree: true,
		});
	}

	disconnectedCallback() {
		this.mutationObserver.disconnect();
		focusVisible.unobserve(this.tabnav);
		this.resizeObserver?.unobserve(this.navEl);
	}

	/** Shows the specified tab panel. */
	@Method()
	async show(panel: string) {
		const tabs = this.getAllTabs();
		const tab = tabs.find((el) => el.panel === panel);

		if (tab) {
			this.setActiveTab(tab);
		}
	}

	@Watch("collapsed")
	toggleTab() {
		this.getAllTabs().forEach((tab) => {
			tab.collapsed = this.collapsed;
		});
		const tabPopovers = this.host.querySelectorAll("hbr-tab-popover");
		if (tabPopovers) {
			tabPopovers.forEach((popoverTab) => {
				popoverTab.collapsed = this.collapsed;
			});
		}
	}

	getAllTabs(includeDisabled = false, ele?, isAll = true) {
		let slot = ele;
		if (!ele) slot = this.tabs.querySelector("slot");
		const slotList = [...slot.assignedElements()];
		const tabList = slotList.reduce((acc, cur) => {
			if (cur.tagName.toLowerCase() === "hbr-tab" && !cur.disabled)
				acc.push(cur);
			if (cur.tagName.toLowerCase() === "hbr-tab-fold" && !cur.disabled) {
				acc.push(cur);
				if (cur.open || isAll) {
					const slot = cur?.shadowRoot?.querySelector(
						"slot:not([name='label'])",
					);
					if (slot) acc.push(...this.getAllTabs(includeDisabled, slot));
				}
			}
			if (cur.tagName.toLowerCase() === "hbr-tab-popover") {
				const tab = cur?.shadowRoot.querySelector("hbr-tab");
				if (tab) {
					acc.push(tab);
				}
			}
			return acc;
		}, []);
		return tabList;
	}

	getAllPanels() {
		const slot = this.body.querySelector("slot");
		return [...slot.assignedElements()].filter(
			(el: HTMLElement) => el.tagName.toLowerCase() === "hbr-tab-panel",
		) as [HTMLHbrTabPanelElement];
	}

	getAllTabFold() {
		const slot = this.tabs.querySelector("slot");
		return [...slot.assignedElements()].filter(
			(el: HTMLElement) => el.tagName.toLowerCase() === "hbr-tab-fold",
		) as [HTMLHbrTabFoldElement];
	}

	getActiveTab() {
		return this.getAllTabs().find((el) => el.active);
	}

	closeAllPopovers() {
		const slot = this.tabs.querySelector("slot");
		const slotList = [...slot.assignedElements()];
		slotList.forEach((cur: HTMLHbrTabPopoverElement) => {
			if (cur.tagName.toLowerCase() === "hbr-tab-popover") {
				cur.removeFocus(null);
			}
		});
	}

	handleClick(event: MouseEvent) {
		if (this.uncontrolled) return;
		const target = event.target as HTMLElement;
		const tab = target.closest("hbr-tab");
		const tabnav = tab?.closest("hbr-tab-nav");
		// Ensure the target tab is in this tab group
		if (tabnav !== this.host) {
			return false;
		}

		if (tab) {
			this.setActiveTab(tab);
		}
		this.isVisible = !this.isVisible;
	}

	handleClickIcon() {
		this.isVisible = !this.isVisible;
	}

	handleKeyDown(event: KeyboardEvent) {
		if (this.uncontrolled) return;
		const target = event.target as HTMLElement;
		let tab: HTMLHbrTabElement;
		let popover: HTMLHbrTabPopoverElement;
		let tabnav: HTMLHbrTabNavElement;
		if (target.tagName.toLowerCase() === "hbr-tab-popover") {
			popover = target as HTMLHbrTabPopoverElement;
			tab = target.shadowRoot.querySelector("hbr-tab");
			tabnav = popover?.closest("hbr-tab-nav");
		} else {
			tab = target.closest("hbr-tab");
			popover = target.closest("hbr-tab-popover");
			tabnav = tab?.closest("hbr-tab-nav") || popover?.closest("hbr-tab-nav");
		}

		// Ensure the target tab is in this tab group
		if (tabnav !== this.host) {
			return false;
		}

		// Activate a tab
		if (["Enter", " "].includes(event.key)) {
			if (tab && !popover) {
				if (this.uncontrolled) return;
				this.setActiveTab(tab);
				event.preventDefault();
				this.isVisible = false;
			} else if (popover) {
				const popoverBlock = document.getElementById(popover.contentId);
				const menuItem = popoverBlock.querySelector("hbr-menu-item");
				menuItem?.setFocus();
			}
		}

		if (["ArrowLeft", "ArrowRight"].includes(event.key)) {
			if (popover && event.key === "ArrowRight") {
				const poperBlock = document.getElementById(popover.contentId);
				const menuItem = poperBlock.querySelector("hbr-menu-item");
				menuItem?.setFocus();
			}
		}

		// Move focus up or down
		if (
			["ArrowUp", "ArrowDown", "Home", "End", "Tab", "ArrowLeft"].includes(
				event.key,
			)
		) {
			const activeEl = document.activeElement as HTMLElement;
			const targetPopover = activeEl.closest("hbr-tab-popover");
			const isTab =
				activeEl &&
				["hbr-tab", "hbr-tab-fold", "hbr-tab-popover"].includes(
					activeEl.tagName.toLowerCase(),
				);
			if (isTab || popover) {
				const tabs = this.getAllTabs(false, false, false);
				let popover: HTMLHbrTabPopoverElement;
				let tab: HTMLHbrTabElement;
				if (activeEl.tagName.toLowerCase() === "hbr-tab-popover") {
					popover = target as HTMLHbrTabPopoverElement;
					tab = popover.shadowRoot.querySelector("hbr-tab");
				} else if (activeEl.tagName.toLowerCase() === "hbr-tab") {
					tab = activeEl as HTMLHbrTabElement;
					popover = tab?.closest("hbr-tab-popover");
				} else {
					popover = targetPopover;
					tab = popover.shadowRoot.querySelector("hbr-tab");
				}

				let index = tabs.indexOf(tab);
				if (event.key === "Home") {
					index = 0;
				} else if (event.key === "End") {
					index = tabs.length - 1;
				} else if (
					event.key === "ArrowUp" ||
					(event.key === "Tab" && event.shiftKey && isTab)
				) {
					index = Math.max(0, index - 1);
				} else if (
					event.key === "ArrowDown" ||
					(event.key === "Tab" && !event.shiftKey && isTab)
				) {
					index = Math.min(tabs.length - 1, index + 1);
				}

				tab = tabs[index];
				if (tab && tab.tagName.toLowerCase() === "hbr-tab") {
					const basePart = tab.shadowRoot.querySelector("div[part='base']");
					const tabindex = basePart.getAttribute("tabindex");
					if (popover) {
						popover.removeFocus(null);
					}
					tabindex === "0" && tab.setFocus({ preventScroll: true });
				} else if (tab && tab.tagName.toLowerCase() === "hbr-tab-fold") {
					tab.setFocus({ preventScroll: true });
				}

				event.preventDefault();
			}
		}
	}

	setActiveTab(tab: HTMLHbrTabElement, emitEvents = true) {
		const isNestedTab = tab?.closest("hbr-tab-panel");
		if (isNestedTab && this.host.contains(isNestedTab)) return;
		if (tab && tab !== this.activeTab && !tab.disabled) {
			const previousTab = this.activeTab;
			this.activeTab = tab;

			// Sync tabs and panels
			this.getAllTabs().forEach((el) => {
				el.active = el === this.activeTab;
			});
			this.getAllTabFold().forEach((el) => {
				if (el.contains(tab) && !el.open) el.active = true;
				else el.active = false;
			});
			this.getAllPanels().forEach((el) => {
				el.active = el.name === this.activeTab.panel;
			});

			// Emit events
			if (emitEvents) {
				if (previousTab) {
					this.hbrTabHide.emit({ name: previousTab.panel });
				}

				this.hbrTabShow.emit({ name: this.activeTab.panel });
			}
		}
	}

	setAriaLabels() {
		const tabs = this.getAllTabs();
		const panels = this.getAllPanels();

		// Link each tab with its corresponding panel
		tabs.map((tab) => {
			const panel = panels.find((el) => el.name === tab.panel);
			if (panel) {
				tab.setAttribute("aria-controls", panel.getAttribute("id"));
				panel.setAttribute("aria-labelledby", tab.getAttribute("id"));
			}
		});
	}

	render() {
		const customSystemIcons = getBootstrapConfig()?.systemIcons;
		return (
			<Host
				style={{
					"--sentiment-color": `${color(this.sentiment)}`,
				}}
			>
				<div
					part="base"
					ref={(el) => {
						this.tabnav = el;
					}}
					class={{
						"tab-nav": true,
						"tab-nav--collapsed": this.collapsed,
					}}
					onClick={this.handleClick}
					onKeyDown={this.handleKeyDown}
				>
					<div
						class={{
							"tab-nav__nav-container": true,
							"tab-visible": this.isVisible,
							"tab-nav__nav-container-no-responsive": this.noResponsive,
						}}
					>
						<hbr-icon-button
							class={{
								"tab-nav__close-icon": true,
								"tab-nav__close-icon-no-responsive": this.noResponsive,
							}}
							onClick={this.handleClickIcon}
							asset={customSystemIcons?.remove || remove}
							arialabel="Close menu"
						/>
						<div
							ref={(el) => {
								this.navEl = el;
							}}
							key="nav"
							part="nav"
							class="tab-nav__nav"
						>
							<div
								ref={(el) => {
									this.tabs = el;
								}}
								part="tabs"
								class={{
									"tab-nav__tabs": true,
									"tab-nav__tabs-nav": this.nav,
									"tab-nav__tabs-nav--collapsed": this.collapsed,
								}}
								role="menubar"
								aria-orientation="vertical"
							>
								<slot />
							</div>
						</div>
					</div>

					<span
						part="border"
						class={{
							"tab-nav__resizer": true,
							"tab-nav__resizer-border": this.border,
						}}
					/>

					<div
						ref={(el) => {
							this.body = el;
						}}
						part="body"
						class="tab-nav__body"
					>
						<slot name="content" />
					</div>
				</div>
			</Host>
		);
	}
}
